def transform(grid):
    # Split the four 5x5 panels, then stack them vertically in their original order.
    panels = [
        [row[start:start + 5] for row in grid]
        for start in (0, 6, 12, 18)
    ]
    out = []
    for i, panel in enumerate(panels):
        if i:
            out.append([6] * 5)
        out.extend([row[:] for row in panel])
    return out
